                       int(shape3(2), kind=c_intptr_t) * &
                       int(shape3(3), kind=c_intptr_t)

      base_addr = int(f_out(field), kind=c_intptr_t)

      do chunk = 1, nchunks(field)

        chunk_offset = int(chunk-1, kind=c_intptr_t) * &
                       chunk_elements * element_bytes

        chunk_addr = base_addr + chunk_offset

        p_out = transfer(chunk_addr, c_null_ptr)

        call c_f_pointer(p_out, field_out, shape3)

        do s3 = storage_lo(3), storage_hi(3)
          do s2 = storage_lo(2), storage_hi(2)
            do s1 = storage_lo(1), storage_hi(1)

              pos = pos + 1
              field_out(s1,s2,s3) = buffer(pos)

            enddo
          enddo
        enddo

      enddo
    enddo

    if (pos - buffer_pos /= d_comm%R_msize(list) * total_chunks) then
      call mpp_error(FATAL, &
           'MPP_DO_REDISTRIBUTE_3D_: unpacked receive size mismatch')
    endif

    buffer_pos = pos

  enddo

  call mpp_sync_self()

end subroutine mpp_do_redistribute_i8_3D
