if( group%k_loop_inside ) then
! nvfortran + cray pointers imposes some restrictions on the loops below:
!   * the compiler cannot privatise OpenMP cray pointers in offloaded loops. Hence, inner loops
!     must be ported rather than the whole outer loop.
!   * the more verbose form of openmp offload loops must be used. Would prefer "target teams loop".
!   * default(shared) must be used otherwise loops hang or segfault. Would prefer "default(none)".

!$OMP parallel do default(shared) shared(npack,group,ptr,nvector,ksize,buffer_start_pos) &
!$OMP                          private(buffer_pos,pos,m,is,ie,js,je,rotation, &
!$OMP                                  ptr_field, ptr_fieldx, ptr_fieldy,n,k,ni,nj,idx)

  do n = 1, npack
     buffer_pos = group%pack_buffer_pos(n) + buffer_start_pos
     pos  = buffer_pos
     is = group%pack_is(n); ie = group%pack_ie(n); ni = ie-is+1
     js = group%pack_js(n); je = group%pack_je(n); nj = je-js+1
     rotation = group%pack_rotation(n)
     if( group%pack_type(n) == FIELD_S ) then
        select case( rotation )
        case(ZERO)
           do l=1, group%nscalar  ! loop over number of fields
              ptr_field = group%addrs_s(l)





              do k = 1, ksize
                 do j = js, je
                    do i = is, ie
                       idx = pos + (k-1)*nj*ni + (j-js)*ni + (i-is) + 1
                       buffer(idx) = field(i,j,k)
                    end do
                 end do
              enddo
              pos = pos + ksize*nj*ni
           enddo
        case( MINUS_NINETY )
           do l=1,group%nscalar  ! loop over number of fields
              ptr_field = group%addrs_s(l)





              do k = 1, ksize
                 do i = is, ie
                    do j = je, js, -1
                       idx = pos + (k-1)*nj*ni + (i-is)*nj + (je-j) + 1
                       buffer(idx) = field(i,j,k)
                    end do
                 end do
              end do
              pos = pos + ksize*nj*ni
           end do
        case( NINETY )
           do l=1,group%nscalar  ! loop over number of fields
              ptr_field = group%addrs_s(l)





              do k = 1, ksize
                 do i = ie, is, -1
                    do j = js, je
                       idx = pos + (k-1)*nj*ni + (ie-i)*nj + (j-js) + 1
                       buffer(idx) = field(i,j,k)
                    end do
                 end do
              end do
              pos = pos + ksize*nj*ni
           end do
        case( ONE_HUNDRED_EIGHTY )
           do l=1,group%nscalar  ! loop over number of fields
              ptr_field = group%addrs_s(l)





              do k = 1, ksize
                 do j = je, js, -1
                    do i = ie, is, -1
                       idx = pos + (k-1)*nj*ni + (je-j)*ni + (ie-i) + 1
                       buffer(idx) = field(i,j,k)
                    end do
                 end do
              end do
              pos = pos + ksize*nj*ni
           end do
        end select
     else if( group%pack_type(n) == FIELD_X  ) then
        select case( rotation )
        case(ZERO)
           do l=1, nvector  ! loop over number of fields
              ptr_fieldx = group%addrs_x(l)





              do k = 1, ksize
                 do j = js, je
                    do i = is, ie
                       idx = pos + (k-1)*nj*ni + (j-js)*ni + (i-is) + 1
                       buffer(idx) = fieldx(i,j,k)
                    end do
                 end do
              end do
              pos = pos + ksize*nj*ni
           end do
        case( MINUS_NINETY )
           if( BTEST(group%flags_v,SCALAR_BIT) ) then
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldy = group%addrs_y(l)





                 do k = 1, ksize
                    do i = is, ie
                       do j = je, js, -1
                        idx = pos + (k-1)*nj*ni + (i-is)*nj + (je-j) + 1
                        buffer(idx) = fieldy(i,j,k)
                       end do
                    end do
                 end do
                 pos = pos + ksize*nj*ni
              end do
           else
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldy = group%addrs_y(l)





                 do k = 1, ksize
                    do i = is, ie
                       do j = je, js, -1
                          idx = pos + (k-1)*nj*ni + (i-is)*nj + (je-j) + 1
                          buffer(idx) = -fieldy(i,j,k)
                       end do
                    end do
                 end do
                 pos = pos + ksize*nj*ni
              end do
           end if
        case( NINETY )
           do l=1, nvector  ! loop over number of fields
              ptr_fieldy = group%addrs_y(l)





              do k = 1, ksize
                 do i = ie, is, -1
                    do j = js, je
                     !   pos = pos + 1
                     !   buffer(pos) = fieldy(i,j,k)
                       idx = pos + (k-1)*nj*ni + (ie-i)*nj + (j-js) + 1
                       buffer(idx) = fieldy(i,j,k)
                    end do
                 end do
              end do
              pos = pos + ksize*nj*ni
           end do
        case( ONE_HUNDRED_EIGHTY )
           if( BTEST(group%flags_v,SCALAR_BIT) ) then
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldx = group%addrs_x(l)





                 do k = 1, ksize
                    do j = je, js, -1
                       do i = ie, is, -1
                          idx = pos + (k-1)*nj*ni + (je-j)*ni + (ie-i) + 1
                          buffer(idx) = fieldx(i,j,k)
                       end do
                    end do
                 end do
                 pos = pos + ksize*nj*ni
              end do
           else
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldx = group%addrs_x(l)





                 do k = 1, ksize
                    do j = je, js, -1
                       do i = ie, is, -1
                          idx = pos + (k-1)*nj*ni + (je-j)*ni + (ie-i) + 1
                          buffer(idx) = -fieldx(i,j,k)
                       end do
                    end do
                 end do
                 pos = pos + ksize*nj*ni
              end do
           end if
        end select ! select case( rotation(n) )
     else if( group%pack_type(n) == FIELD_Y ) then
        select case( rotation )
        case(ZERO)
           do l=1, nvector  ! loop over number of fields
              ptr_fieldy = group%addrs_y(l)





              do k = 1, ksize
                 do j = js, je
                    do i = is, ie
                       idx = pos + (k-1)*nj*ni + (j-js)*ni + (i-is) + 1
                       buffer(idx) = fieldy(i,j,k)
                    end do
                 end do
              end do
              pos = pos + ksize*nj*ni
           end do
        case( MINUS_NINETY )
           do l=1,nvector  ! loop over number of fields
              ptr_fieldx = group%addrs_x(l)





              do k = 1, ksize
                 do i = is, ie
                    do j = je, js, -1
                     idx = pos + (k-1)*nj*ni + (i-is)*nj + (je-j) + 1
                     buffer(idx) = fieldx(i,j,k)
                    end do
                 end do
              end do
              pos = pos + ksize*nj*ni
           end do
        case( NINETY )
           if( BTEST(group%flags_v,SCALAR_BIT) ) then
              do l=1, nvector  ! loop over number of fields
                 ptr_fieldx = group%addrs_x(l)





                 do k = 1, ksize
                    do i = ie, is, -1
                       do j = js, je
                          idx = pos + (k-1)*nj*ni + (ie-i)*nj + (j-js) + 1
                          buffer(idx) = fieldx(i,j,k)
                       end do
                    end do
                 end do
                 pos = pos + ksize*nj*ni
              end do
           else
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldx = group%addrs_x(l)





                 do k = 1, ksize
                    do i = ie, is, -1
                       do j = js, je
                          idx = pos + (k-1)*nj*ni + (ie-i)*nj + (j-js) + 1
                          buffer(idx) = -fieldx(i,j,k)
                       end do
                    end do
                 end do
                 pos = pos + ksize*nj*ni
              end do
           end if
        case( ONE_HUNDRED_EIGHTY )
           if( BTEST(group%flags_v,SCALAR_BIT) ) then
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldy = group%addrs_y(l)





                 do k = 1, ksize
                    do j = je, js, -1
                       do i = ie, is, -1
                          idx = pos + (k-1)*nj*ni + (je-j)*ni + (ie-i) + 1
                          buffer(idx) = fieldy(i,j,k)
                       end do
                    end do
                 end do
                 pos = pos + ksize*nj*ni
              end do
           else
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldy = group%addrs_y(l)





                 do k = 1, ksize
                    do j = je, js, -1
                       do i = ie, is, -1
                          idx = pos + (k-1)*nj*ni + (je-j)*ni + (ie-i) + 1
                          buffer(idx) = -fieldy(i,j,k)
                       end do
                    end do
                 end do
                 pos = pos + ksize*nj*ni
              end do
           end if
        end select ! select case( rotation(n) )
     endif
  enddo
