  call mpp_clock_end(group_unpk_clock)

  ! ---northern boundary fold
  ! below omp offload loops have maps excluded as gcc doesn't support cray pointers in maps
  shift = 0
  if(domain%symmetry) shift = 1
  if( nvector >0 .AND. BTEST(domain%fold,NORTH) .AND. (.NOT.BTEST(flags_v,SCALAR_BIT)) )then
     j = domain%y(1)%global%end+shift
     if( domain%y(1)%domain_data%begin.LE.j .AND. j.LE.domain%y(1)%domain_data%end+shift )then !fold is within domain
        !poles set to 0: BGRID only
        if( gridtype.EQ.BGRID_NE )then
           midpoint = (domain%x(1)%global%begin+domain%x(1)%global%end-1+shift)/2
           j  = domain%y(1)%global%end+shift
           is = domain%x(1)%global%begin; ie = domain%x(1)%global%end+shift
           if( .NOT. domain%symmetry ) is = is - 1
           isd = domain%x(1)%domain_data%begin
           do i = is ,ie, midpoint
              if( isd.LE.i .AND. i.LE. domain%x(1)%domain_data%end+shift )then
                 do l=1,nvector
                    ptr_fieldx = group%addrs_x(l)
                    ptr_fieldy = group%addrs_y(l)
                    if (use_device_ptr) then
                       !$omp target teams distribute parallel do default(shared) &
                       !$omp   shared(ksize, ptr_fieldx, ptr_fieldy)
                       do k = 1,ksize
                          fieldx(i,j,k) = 0.
                          fieldy(i,j,k) = 0.
                       end do
                    else
                       do k = 1,ksize
                          fieldx(i,j,k) = 0.
                          fieldy(i,j,k) = 0.
                       end do
                    end if
                 end do
              end if
           end do
        endif
        ! the following code code block correct an error where the data in your halo coming from
        ! other half may have the wrong sign
        !off west edge, when update north or west direction
        j = domain%y(1)%global%end+shift
        if ( recv_y(7) .OR. recv_y(5) ) then
           select case(gridtype)
           case(BGRID_NE)
              if(domain%symmetry) then
                 is = domain%x(1)%global%begin
              else
                 is = domain%x(1)%global%begin - 1
              end if
              isd = domain%x(1)%domain_data%begin
              if( is.GT.isd )then

                 if( 2*is-isd.GT.domain%x(1)%domain_data%end+shift ) &
                      call mpp_error( FATAL, 'MPP_DO_UPDATE_V: folded-north BGRID_NE west edge ubound error.' )
                 do l=1,nvector
                    ptr_fieldx = group%addrs_x(l)
                    ptr_fieldy = group%addrs_y(l)
                    if (use_device_ptr) then
                       !$omp target teams distribute parallel do collapse(2) default(shared) &
                       !$omp   shared(ksize, isd, is, ptr_fieldx, ptr_fieldy)
                       do k = 1,ksize
                          do i = isd,is-1
                             fieldx(i,j,k) = fieldx(2*is-i,j,k)
                             fieldy(i,j,k) = fieldy(2*is-i,j,k)
                          end do
                       end do
                    else
                       do k = 1,ksize
                          do i = isd,is-1
                             fieldx(i,j,k) = fieldx(2*is-i,j,k)
                             fieldy(i,j,k) = fieldy(2*is-i,j,k)
                          end do
                       end do
                    endif
                 end do
              end if
           case(CGRID_NE)
              is = domain%x(1)%global%begin
              isd = domain%x(1)%compute%begin - group%whalo_v
              if( is.GT.isd )then
                 if( 2*is-domain%x(1)%domain_data%begin-1.GT.domain%x(1)%domain_data%end ) &
                      call mpp_error( FATAL, 'MPP_DO_UPDATE_V: folded-north CGRID_NE west edge ubound error.' )
                 do l=1,nvector
                    ptr_fieldy = group%addrs_y(l)
                    if (use_device_ptr) then
                       !$omp target teams distribute parallel do collapse(2) default(shared) &
                       !$omp   shared(ksize, isd, is, ptr_fieldy)
                       do k = 1,ksize
                          do i = isd,is-1
                             fieldy(i,j,k) = fieldy(2*is-i-1,j,k)
                          end do
                       end do
                    else
                       do k = 1,ksize
                          do i = isd,is-1
                             fieldy(i,j,k) = fieldy(2*is-i-1,j,k)
                          end do
                       end do
                    end if
                 end do
              end if
           end select
        end if
        !off east edge
        is = domain%x(1)%global%end
        if(domain%x(1)%cyclic .AND. is.LT.domain%x(1)%domain_data%end )then
           ie = domain%x(1)%compute%end+group%ehalo_v
           is = is + 1
           select case(gridtype)
           case(BGRID_NE)
              is = is + shift
              ie = ie + shift
              do l=1,nvector
                 ptr_fieldx = group%addrs_x(l)
                 ptr_fieldy = group%addrs_y(l)
                 if (use_device_ptr) then
                    !$omp target teams distribute parallel do collapse(2) default(shared) &
                    !$omp   shared(ksize, is, ie, ptr_fieldx, ptr_fieldy)
                    do k = 1,ksize
                       do i = is,ie
                          fieldx(i,j,k) = -fieldx(i,j,k)
                          fieldy(i,j,k) = -fieldy(i,j,k)
                       end do
                    end do
                 else
                    do k = 1,ksize
                       do i = is,ie
                          fieldx(i,j,k) = -fieldx(i,j,k)
                          fieldy(i,j,k) = -fieldy(i,j,k)
                       end do
                    end do
                 end if
              end do
           case(CGRID_NE)
              do l=1,nvector
                 ptr_fieldy = group%addrs_y(l)
                 if (use_device_ptr) then
                    !$omp target teams distribute parallel do collapse(2) default(shared) &
                    !$omp   shared(ksize, is, ie, ptr_fieldy)
                    do k = 1,ksize
                       do i = is, ie
                          fieldy(i,j,k) = -fieldy(i,j,k)
                       end do
                    end do
                 else
                    do k = 1,ksize
                       do i = is, ie
                          fieldy(i,j,k) = -fieldy(i,j,k)
                       end do
                    end do
                 end if
              end do
           end select
        end if
     end if
  else if( BTEST(domain%fold,SOUTH) .OR. BTEST(domain%fold,WEST) .OR. BTEST(domain%fold,EAST) ) then
     call mpp_error(FATAL, "MPP_DO_GROUP_UPDATE: this interface does not support folded_south, " // &
          "folded_west of folded_east, contact developer")
  endif

  if(nsend>0) then
     call mpp_clock_begin(group_wait_clock)
     call mpp_sync_self( )
     call mpp_clock_end(group_wait_clock)
  endif

end subroutine mpp_do_group_update_r8


subroutine mpp_start_group_update_r8(group, domain, d_type, reuse_buffer)
  type(mpp_group_update_type), intent(inout) :: group
  type(domain2D),              intent(inout) :: domain
  real(r8_kind),                   intent(in)    :: d_type
  logical,  optional,          intent(in)    :: reuse_buffer

  integer   :: nscalar, nvector
  integer   :: nsend, nrecv, flags_v
  integer   :: msgsize, npack, rotation
  integer   :: from_pe, to_pe, buffer_pos, pos, idx
  integer   :: ksize, is, ie, js, je
  integer   :: n, l, m, i, j, k, buffer_start_pos, ni, nj, nk
  logical   :: reuse_buf_pos
  logical, parameter :: use_device_ptr = .false. ! placeholder
  character(len=8)            :: text

  real(r8_kind) :: buffer(size(mpp_domains_stack_nonblock(:)))
  real(r8_kind) :: field (group%is_s:group%ie_s,group%js_s:group%je_s, group%ksize_s)
  real(r8_kind) :: fieldx(group%is_x:group%ie_x,group%js_x:group%je_x, group%ksize_v)
  real(r8_kind) :: fieldy(group%is_y:group%ie_y,group%js_y:group%je_y, group%ksize_v)
  pointer( ptr, buffer )
  pointer(ptr_field, field)
  pointer(ptr_fieldx, fieldx)
  pointer(ptr_fieldy, fieldy)

  nscalar = group%nscalar
  nvector = group%nvector

  if(nscalar>0) then
     ksize = group%ksize_s
  else
     ksize = group%ksize_v
  endif

  !--- set reset_index_s and reset_index_v to 0
  group%reset_index_s = 0
  group%reset_index_v = 0

  reuse_buf_pos = .FALSE.
  if (PRESENT(reuse_buffer)) reuse_buf_pos = reuse_buffer

  if (.not. group%initialized) then
    call set_group_update(group,domain)
  endif

  if (.not. reuse_buf_pos) then
     group%buffer_start_pos = nonblock_group_buffer_pos
     nonblock_group_buffer_pos = nonblock_group_buffer_pos + group%tot_msgsize
     mpp_domains_stack_hwm = nonblock_group_buffer_pos + 1
     if( mpp_domains_stack_hwm .GT. mpp_domains_stack_size )then
        write( text,'(i8)' )mpp_domains_stack_hwm
        call mpp_error( FATAL, 'set_group_update: mpp_domains_stack overflow, '// &
                     'call mpp_domains_set_stack_size('//trim(text)//') from all PEs.' )
     end if

  else if( group%buffer_start_pos < 0 ) then
     call mpp_error(FATAL, "MPP_START_GROUP_UPDATE: group%buffer_start_pos is not set")
  endif

  nrecv = group%nrecv
  nsend = group%nsend

  ptr = LOC(mpp_domains_stack_nonblock)

  ! Make sure it is not in the middle of the old version of non-blocking halo update.
  if(num_update>0) call mpp_error(FATAL, "MPP_START_GROUP_UPDATE: can not be called in the middle of "// &
              "mpp_start_update_domains/mpp_complete_update_domains call")

  num_nonblock_group_update = num_nonblock_group_update + 1

  !---pre-post receive.
  call mpp_clock_begin(nonblock_group_recv_clock)
  do m = 1, nrecv
     msgsize = group%recv_size(m)
     from_pe = group%from_pe(m)
     if( msgsize .GT. 0 )then
        buffer_pos = group%buffer_pos_recv(m) + group%buffer_start_pos
        call mpp_recv( buffer(buffer_pos+1), glen=msgsize, from_pe=from_pe, block=.false., &
             tag=COMM_TAG_1, request=group%request_recv(m))
        group%type_recv(m) = MPI_REAL8
     end if
  end do
  call mpp_clock_end(nonblock_group_recv_clock)

  flags_v = group%flags_v

  !pack the data
  call mpp_clock_begin(nonblock_group_pack_clock)
  npack = group%npack
  buffer_start_pos = group%buffer_start_pos
  ! below switch runs OpenMP offloaded packing if ompoffload is .true. and compiled with
  ! OpenMP offload support. Otherwise, run OpenMP CPU by undefining GPU macro if defined
  if (use_device_ptr) then

# 1 "mpp/include/group_update_pack.inc" 1
!***********************************************************************
!*                             Apache License 2.0
!*
!* This file is part of the GFDL Flexible Modeling System (FMS).
!*
!* Licensed under the Apache License, Version 2.0 (the "License");
!* you may not use this file except in compliance with the License.
!* You may obtain a copy of the License at
!*
!*     http://www.apache.org/licenses/LICENSE-2.0
!*
!* FMS is distributed in the hope that it will be useful, but WITHOUT
!* WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied;
!* without even the implied warranty of MERCHANTABILITY or FITNESS FOR A
!* PARTICULAR PURPOSE. See the License for the specific language
!* governing permissions and limitations under the License.
!***********************************************************************

if( group%k_loop_inside ) then
! nvfortran + cray pointers imposes some restrictions on the loops below:
!   * the compiler cannot privatise OpenMP cray pointers in offloaded loops. Hence, inner loops
!     must be ported rather than the whole outer loop.
!   * the more verbose form of openmp offload loops must be used. Would prefer "target teams loop".
!   * default(shared) must be used otherwise loops hang or segfault. Would prefer "default(none)".

!$OMP parallel do default(shared) shared(npack,group,ptr,nvector,ksize,buffer_start_pos) &
!$OMP                          private(buffer_pos,pos,m,is,ie,js,je,rotation, &
!$OMP                                  ptr_field, ptr_fieldx, ptr_fieldy,n,k,ni,nj,idx)

  do n = 1, npack
     buffer_pos = group%pack_buffer_pos(n) + buffer_start_pos
     pos  = buffer_pos
     is = group%pack_is(n); ie = group%pack_ie(n); ni = ie-is+1
     js = group%pack_js(n); je = group%pack_je(n); nj = je-js+1
     rotation = group%pack_rotation(n)
     if( group%pack_type(n) == FIELD_S ) then
        select case( rotation )
        case(ZERO)
           do l=1, group%nscalar  ! loop over number of fields
              ptr_field = group%addrs_s(l)





              do k = 1, ksize
                 do j = js, je
                    do i = is, ie
                       idx = pos + (k-1)*nj*ni + (j-js)*ni + (i-is) + 1
                       buffer(idx) = field(i,j,k)
                    end do
                 end do
              enddo
              pos = pos + ksize*nj*ni
           enddo
        case( MINUS_NINETY )
           do l=1,group%nscalar  ! loop over number of fields
              ptr_field = group%addrs_s(l)





              do k = 1, ksize
                 do i = is, ie
                    do j = je, js, -1
                       idx = pos + (k-1)*nj*ni + (i-is)*nj + (je-j) + 1
                       buffer(idx) = field(i,j,k)
                    end do
                 end do
              end do
              pos = pos + ksize*nj*ni
           end do
        case( NINETY )
           do l=1,group%nscalar  ! loop over number of fields
              ptr_field = group%addrs_s(l)





              do k = 1, ksize
                 do i = ie, is, -1
                    do j = js, je
                       idx = pos + (k-1)*nj*ni + (ie-i)*nj + (j-js) + 1
                       buffer(idx) = field(i,j,k)
                    end do
                 end do
              end do
              pos = pos + ksize*nj*ni
           end do
        case( ONE_HUNDRED_EIGHTY )
           do l=1,group%nscalar  ! loop over number of fields
              ptr_field = group%addrs_s(l)





              do k = 1, ksize
                 do j = je, js, -1
                    do i = ie, is, -1
                       idx = pos + (k-1)*nj*ni + (je-j)*ni + (ie-i) + 1
                       buffer(idx) = field(i,j,k)
                    end do
                 end do
              end do
              pos = pos + ksize*nj*ni
           end do
        end select
     else if( group%pack_type(n) == FIELD_X  ) then
        select case( rotation )
        case(ZERO)
           do l=1, nvector  ! loop over number of fields
              ptr_fieldx = group%addrs_x(l)





              do k = 1, ksize
                 do j = js, je
                    do i = is, ie
                       idx = pos + (k-1)*nj*ni + (j-js)*ni + (i-is) + 1
                       buffer(idx) = fieldx(i,j,k)
                    end do
                 end do
              end do
              pos = pos + ksize*nj*ni
           end do
        case( MINUS_NINETY )
           if( BTEST(group%flags_v,SCALAR_BIT) ) then
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldy = group%addrs_y(l)





                 do k = 1, ksize
                    do i = is, ie
                       do j = je, js, -1
                        idx = pos + (k-1)*nj*ni + (i-is)*nj + (je-j) + 1
                        buffer(idx) = fieldy(i,j,k)
                       end do
                    end do
                 end do
                 pos = pos + ksize*nj*ni
              end do
           else
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldy = group%addrs_y(l)





                 do k = 1, ksize
                    do i = is, ie
                       do j = je, js, -1
                          idx = pos + (k-1)*nj*ni + (i-is)*nj + (je-j) + 1
                          buffer(idx) = -fieldy(i,j,k)
                       end do
                    end do
                 end do
                 pos = pos + ksize*nj*ni
              end do
           end if
        case( NINETY )
           do l=1, nvector  ! loop over number of fields
              ptr_fieldy = group%addrs_y(l)





              do k = 1, ksize
                 do i = ie, is, -1
                    do j = js, je
                     !   pos = pos + 1
                     !   buffer(pos) = fieldy(i,j,k)
                       idx = pos + (k-1)*nj*ni + (ie-i)*nj + (j-js) + 1
                       buffer(idx) = fieldy(i,j,k)
                    end do
                 end do
              end do
              pos = pos + ksize*nj*ni
           end do
        case( ONE_HUNDRED_EIGHTY )
           if( BTEST(group%flags_v,SCALAR_BIT) ) then
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldx = group%addrs_x(l)





                 do k = 1, ksize
                    do j = je, js, -1
                       do i = ie, is, -1
                          idx = pos + (k-1)*nj*ni + (je-j)*ni + (ie-i) + 1
                          buffer(idx) = fieldx(i,j,k)
                       end do
                    end do
                 end do
                 pos = pos + ksize*nj*ni
              end do
           else
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldx = group%addrs_x(l)





                 do k = 1, ksize
                    do j = je, js, -1
                       do i = ie, is, -1
                          idx = pos + (k-1)*nj*ni + (je-j)*ni + (ie-i) + 1
                          buffer(idx) = -fieldx(i,j,k)
                       end do
                    end do
                 end do
                 pos = pos + ksize*nj*ni
              end do
           end if
        end select ! select case( rotation(n) )
     else if( group%pack_type(n) == FIELD_Y ) then
        select case( rotation )
        case(ZERO)
           do l=1, nvector  ! loop over number of fields
              ptr_fieldy = group%addrs_y(l)





              do k = 1, ksize
                 do j = js, je
                    do i = is, ie
                       idx = pos + (k-1)*nj*ni + (j-js)*ni + (i-is) + 1
                       buffer(idx) = fieldy(i,j,k)
                    end do
                 end do
              end do
              pos = pos + ksize*nj*ni
           end do
        case( MINUS_NINETY )
           do l=1,nvector  ! loop over number of fields
              ptr_fieldx = group%addrs_x(l)





              do k = 1, ksize
                 do i = is, ie
                    do j = je, js, -1
                     idx = pos + (k-1)*nj*ni + (i-is)*nj + (je-j) + 1
                     buffer(idx) = fieldx(i,j,k)
                    end do
                 end do
              end do
              pos = pos + ksize*nj*ni
           end do
        case( NINETY )
           if( BTEST(group%flags_v,SCALAR_BIT) ) then
              do l=1, nvector  ! loop over number of fields
                 ptr_fieldx = group%addrs_x(l)





                 do k = 1, ksize
                    do i = ie, is, -1
                       do j = js, je
                          idx = pos + (k-1)*nj*ni + (ie-i)*nj + (j-js) + 1
                          buffer(idx) = fieldx(i,j,k)
                       end do
                    end do
                 end do
                 pos = pos + ksize*nj*ni
              end do
           else
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldx = group%addrs_x(l)





                 do k = 1, ksize
                    do i = ie, is, -1
                       do j = js, je
                          idx = pos + (k-1)*nj*ni + (ie-i)*nj + (j-js) + 1
                          buffer(idx) = -fieldx(i,j,k)
                       end do
                    end do
                 end do
                 pos = pos + ksize*nj*ni
              end do
           end if
        case( ONE_HUNDRED_EIGHTY )
           if( BTEST(group%flags_v,SCALAR_BIT) ) then
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldy = group%addrs_y(l)





                 do k = 1, ksize
                    do j = je, js, -1
                       do i = ie, is, -1
                          idx = pos + (k-1)*nj*ni + (je-j)*ni + (ie-i) + 1
                          buffer(idx) = fieldy(i,j,k)
                       end do
                    end do
                 end do
                 pos = pos + ksize*nj*ni
              end do
           else
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldy = group%addrs_y(l)





                 do k = 1, ksize
                    do j = je, js, -1
                       do i = ie, is, -1
                          idx = pos + (k-1)*nj*ni + (je-j)*ni + (ie-i) + 1
                          buffer(idx) = -fieldy(i,j,k)
                       end do
                    end do
                 end do
                 pos = pos + ksize*nj*ni
              end do
           end if
        end select ! select case( rotation(n) )
     endif
  enddo
else

!$OMP parallel do default(shared) shared(npack,group,ptr,nvector,ksize,buffer_start_pos) &
!$OMP                          private(buffer_pos,pos,m,is,ie,js,je,rotation, &
!$OMP                                  ptr_field, ptr_fieldx, ptr_fieldy,n,k,ni,nj,idx)

  do nk = 1, npack*ksize
     n = (nk-1)/ksize + 1
     k = mod((nk-1), ksize) + 1
     buffer_pos = group%pack_buffer_pos(n) + buffer_start_pos
     pos  = buffer_pos + (k-1)*group%pack_size(n)
     is = group%pack_is(n); ie = group%pack_ie(n); ni = ie-is+1
     js = group%pack_js(n); je = group%pack_je(n); nj = je-js+1
     rotation = group%pack_rotation(n)
     if( group%pack_type(n) == FIELD_S ) then
        select case( rotation )
        case(ZERO)
           do l=1, group%nscalar  ! loop over number of fields
              ptr_field = group%addrs_s(l)





              do j = js, je
                 do i = is, ie
                    idx = pos + (j-js)*ni + (i-is) + 1
                    buffer(idx) = field(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           enddo
        case( MINUS_NINETY )
           do l=1,group%nscalar  ! loop over number of fields
              ptr_field = group%addrs_s(l)





              do i = is, ie
                 do j = je, js, -1
                    idx = pos + (i-is)*nj + (je-j) + 1
                    buffer(idx) = field(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           end do
        case( NINETY )
           do l=1,group%nscalar  ! loop over number of fields
              ptr_field = group%addrs_s(l)





              do i = ie, is, -1
                 do j = js, je
                    idx = pos + (ie-i)*nj + (j-js) + 1
                    buffer(idx) = field(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           end do
        case( ONE_HUNDRED_EIGHTY )
           do l=1,group%nscalar  ! loop over number of fields
              ptr_field = group%addrs_s(l)





              do j = je, js, -1
                 do i = ie, is, -1
                    idx = pos + (je-j)*ni + (ie-i) + 1
                    buffer(idx) = field(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           end do
        end select
     else if( group%pack_type(n) == FIELD_X  ) then
        select case( rotation )
        case(ZERO)
           do l=1, nvector  ! loop over number of fields
              ptr_fieldx = group%addrs_x(l)





              do j = js, je
                 do i = is, ie
                    idx = pos + (j-js)*ni + (i-is) + 1
                    buffer(idx) = fieldx(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           end do
        case( MINUS_NINETY )
           if( BTEST(group%flags_v,SCALAR_BIT) ) then
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldy = group%addrs_y(l)





                 do i = is, ie
                    do j = je, js, -1
                       idx = pos + (i-is)*nj + (je-j) + 1
                       buffer(idx) = fieldy(i,j,k)
                    end do
                 end do
                 pos = pos + nj*ni
              end do
           else
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldy = group%addrs_y(l)





                 do i = is, ie
                    do j = je, js, -1
                       idx = pos + (i-is)*nj + (je-j) + 1
                       buffer(idx) = -fieldy(i,j,k)
                    end do
                 end do
                 pos = pos + nj*ni
              end do
           end if
        case( NINETY )
           do l=1, nvector  ! loop over number of fields
              ptr_fieldy = group%addrs_y(l)





              do i = ie, is, -1
                 do j = js, je
                    idx = pos + (ie-i)*nj + (j-js) + 1
                    buffer(idx) = fieldy(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           end do
        case( ONE_HUNDRED_EIGHTY )
           if( BTEST(group%flags_v,SCALAR_BIT) ) then
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldx = group%addrs_x(l)





                 do j = je, js, -1
                    do i = ie, is, -1
                       idx = pos + (je-j)*ni + (ie-i) + 1
                       buffer(idx) = fieldx(i,j,k)
                    end do
                 end do
                 pos = pos + nj*ni
              end do
           else
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldx = group%addrs_x(l)





                 do j = je, js, -1
                    do i = ie, is, -1
                       idx = pos + (je-j)*ni + (ie-i) + 1
                       buffer(idx) = -fieldx(i,j,k)
                    end do
                 end do
                 pos = pos + nj*ni
              end do
           end if
        end select ! select case( rotation(n) )
     else if( group%pack_type(n) == FIELD_Y ) then
        select case( rotation )
        case(ZERO)
           do l=1, nvector  ! loop over number of fields
              ptr_fieldy = group%addrs_y(l)





              do j = js, je
                 do i = is, ie
                    idx = pos + (j-js)*ni + (i-is) + 1
                    buffer(idx) = fieldy(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           end do
        case( MINUS_NINETY )
           do l=1,nvector  ! loop over number of fields
              ptr_fieldx = group%addrs_x(l)





              do i = is, ie
                 do j = je, js, -1
