     is = group%pack_is(n); ie = group%pack_ie(n); ni = ie-is+1
     js = group%pack_js(n); je = group%pack_je(n); nj = je-js+1
     rotation = group%pack_rotation(n)
     if( group%pack_type(n) == FIELD_S ) then
        select case( rotation )
        case(ZERO)
           do l=1, group%nscalar  ! loop over number of fields
              ptr_field = group%addrs_s(l)





              do j = js, je
                 do i = is, ie
                    idx = pos + (j-js)*ni + (i-is) + 1
                    buffer(idx) = field(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           enddo
        case( MINUS_NINETY )
           do l=1,group%nscalar  ! loop over number of fields
              ptr_field = group%addrs_s(l)





              do i = is, ie
                 do j = je, js, -1
                    idx = pos + (i-is)*nj + (je-j) + 1
                    buffer(idx) = field(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           end do
        case( NINETY )
           do l=1,group%nscalar  ! loop over number of fields
              ptr_field = group%addrs_s(l)





              do i = ie, is, -1
                 do j = js, je
                    idx = pos + (ie-i)*nj + (j-js) + 1
                    buffer(idx) = field(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           end do
        case( ONE_HUNDRED_EIGHTY )
           do l=1,group%nscalar  ! loop over number of fields
              ptr_field = group%addrs_s(l)





              do j = je, js, -1
                 do i = ie, is, -1
                    idx = pos + (je-j)*ni + (ie-i) + 1
                    buffer(idx) = field(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           end do
        end select
     else if( group%pack_type(n) == FIELD_X  ) then
        select case( rotation )
        case(ZERO)
           do l=1, nvector  ! loop over number of fields
              ptr_fieldx = group%addrs_x(l)





              do j = js, je
                 do i = is, ie
                    idx = pos + (j-js)*ni + (i-is) + 1
                    buffer(idx) = fieldx(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           end do
        case( MINUS_NINETY )
           if( BTEST(group%flags_v,SCALAR_BIT) ) then
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldy = group%addrs_y(l)





                 do i = is, ie
                    do j = je, js, -1
                       idx = pos + (i-is)*nj + (je-j) + 1
                       buffer(idx) = fieldy(i,j,k)
                    end do
                 end do
                 pos = pos + nj*ni
              end do
           else
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldy = group%addrs_y(l)





                 do i = is, ie
                    do j = je, js, -1
                       idx = pos + (i-is)*nj + (je-j) + 1
                       buffer(idx) = -fieldy(i,j,k)
                    end do
                 end do
                 pos = pos + nj*ni
              end do
           end if
        case( NINETY )
           do l=1, nvector  ! loop over number of fields
              ptr_fieldy = group%addrs_y(l)





              do i = ie, is, -1
                 do j = js, je
                    idx = pos + (ie-i)*nj + (j-js) + 1
                    buffer(idx) = fieldy(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           end do
        case( ONE_HUNDRED_EIGHTY )
           if( BTEST(group%flags_v,SCALAR_BIT) ) then
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldx = group%addrs_x(l)





                 do j = je, js, -1
                    do i = ie, is, -1
                       idx = pos + (je-j)*ni + (ie-i) + 1
                       buffer(idx) = fieldx(i,j,k)
                    end do
                 end do
                 pos = pos + nj*ni
              end do
           else
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldx = group%addrs_x(l)





                 do j = je, js, -1
                    do i = ie, is, -1
                       idx = pos + (je-j)*ni + (ie-i) + 1
                       buffer(idx) = -fieldx(i,j,k)
                    end do
                 end do
                 pos = pos + nj*ni
              end do
           end if
        end select ! select case( rotation(n) )
     else if( group%pack_type(n) == FIELD_Y ) then
        select case( rotation )
        case(ZERO)
           do l=1, nvector  ! loop over number of fields
              ptr_fieldy = group%addrs_y(l)





              do j = js, je
                 do i = is, ie
                    idx = pos + (j-js)*ni + (i-is) + 1
                    buffer(idx) = fieldy(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           end do
        case( MINUS_NINETY )
           do l=1,nvector  ! loop over number of fields
              ptr_fieldx = group%addrs_x(l)





              do i = is, ie
                 do j = je, js, -1
                    idx = pos + (i-is)*nj + (je-j) + 1
                    buffer(idx) = fieldx(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           end do
        case( NINETY )
           if( BTEST(group%flags_v,SCALAR_BIT) ) then
              do l=1, nvector  ! loop over number of fields
                 ptr_fieldx = group%addrs_x(l)





                 do i = ie, is, -1
                    do j = js, je
                       idx = pos + (ie-i)*nj + (j-js) + 1
                       buffer(idx) = fieldx(i,j,k)
                    end do
                 end do
                 pos = pos + nj*ni
              end do
           else
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldx = group%addrs_x(l)





                 do i = ie, is, -1
                    do j = js, je
                       idx = pos + (ie-i)*nj + (j-js) + 1
                       buffer(idx) = -fieldx(i,j,k)
                    end do
                 end do
                 pos = pos + nj*ni
              end do
           end if
        case( ONE_HUNDRED_EIGHTY )
           if( BTEST(group%flags_v,SCALAR_BIT) ) then
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldy = group%addrs_y(l)





                 do j = je, js, -1
                    do i = ie, is, -1
                       idx = pos + (je-j)*ni + (ie-i) + 1
                       buffer(idx) = fieldy(i,j,k)
                    end do
                 end do
                 pos = pos + nj*ni
              end do
           else
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldy = group%addrs_y(l)





                 do j = je, js, -1
                    do i = ie, is, -1
                       idx = pos + (je-j)*ni + (ie-i) + 1
                       buffer(idx) = -fieldy(i,j,k)
                    end do
                 end do
                 pos = pos + nj*ni
              end do
           end if
        end select ! select case( rotation(n) )
     endif
  enddo
endif
# 519 "mpp/include/mpp_group_update.fh" 2

  endif
  call mpp_clock_end(group_pack_clock)

  call mpp_clock_begin(group_send_clock)
  do n = 1, nsend
     msgsize = group%send_size(n)
     if( msgsize .GT. 0 )then
        buffer_pos = group%buffer_pos_send(n)
        to_pe = group%to_pe(n)
        call mpp_send( buffer(buffer_pos+1), plen=msgsize, to_pe=to_pe, tag=COMM_TAG_1, omp_offload=omp_offload)
     endif
  enddo
  call mpp_clock_end(group_send_clock)

  if(nrecv>0) then
     call mpp_clock_begin(group_wait_clock)
     call mpp_sync_self(check=EVENT_RECV)
     call mpp_clock_end(group_wait_clock)
  endif

  !---unpack the buffer
  nunpack = group%nunpack
  call mpp_clock_begin(group_unpk_clock)
  ! below switch runs OpenMP offloaded unpacking if ompoffload is .true. and compiled with
  ! OpenMP offload support. Otherwise, run OpenMP CPU by undefining GPU macro if defined
  if (use_device_ptr) then

