              ptr_fieldx = group%addrs_x(l)





              do j = js, je
                 do i = is, ie
                    idx = pos + (j-js)*ni + (i-is) + 1
                    buffer(idx) = fieldx(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           end do
