              do l=1,nvector  ! loop over number of fields
                 ptr_fieldy = group%addrs_y(l)





                 do i = is, ie
                    do j = je, js, -1
                       idx = pos + (i-is)*nj + (je-j) + 1
                       buffer(idx) = fieldy(i,j,k)
                    end do
                 end do
                 pos = pos + nj*ni
              end do
           else
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldy = group%addrs_y(l)





                 do i = is, ie
                    do j = je, js, -1
                       idx = pos + (i-is)*nj + (je-j) + 1
                       buffer(idx) = -fieldy(i,j,k)
                    end do
                 end do
                 pos = pos + nj*ni
              end do
           end if
        case( NINETY )
           do l=1, nvector  ! loop over number of fields
              ptr_fieldy = group%addrs_y(l)





              do i = ie, is, -1
                 do j = js, je
                    idx = pos + (ie-i)*nj + (j-js) + 1
                    buffer(idx) = fieldy(i,j,k)
                 end do
              end do
              pos = pos + nj*ni
           end do
        case( ONE_HUNDRED_EIGHTY )
           if( BTEST(group%flags_v,SCALAR_BIT) ) then
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldx = group%addrs_x(l)





                 do j = je, js, -1
                    do i = ie, is, -1
                       idx = pos + (je-j)*ni + (ie-i) + 1
                       buffer(idx) = fieldx(i,j,k)
                    end do
                 end do
                 pos = pos + nj*ni
              end do
           else
              do l=1,nvector  ! loop over number of fields
                 ptr_fieldx = group%addrs_x(l)





                 do j = je, js, -1
                    do i = ie, is, -1
                       idx = pos + (je-j)*ni + (ie-i) + 1
                       buffer(idx) = -fieldx(i,j,k)
                    end do
                 end do
                 pos = pos + nj*ni
              end do
           end if
        end select ! select case( rotation(n) )
     else if( group%pack_type(n) == FIELD_Y ) then
        select case( rotation )
        case(ZERO)
           do l=1, nvector  ! loop over number of fields
              ptr_fieldy = group%addrs_y(l)





              do j = js, je
                 do i = is, ie
                    idx = pos + (j-js)*ni + (i-is) + 1
