              arr(lb(1):ub(1), lb(2):ub(2), lb(3):ub(3), lb(4):ub(4), lb(5):ub(5)) = reshape(vec(1:n), s(1:5))
          end select
        end associate
      end subroutine vec2arr_i4

      !> @brief Initialize an assumed-rank array to `val`. This is used when initializing an assumed-rank array
      !!        outside of a `select rank` block.
      subroutine arr_init_i4 (arr, val)
        integer(i4_kind), dimension(..), intent(out) :: arr !< The array to be initialized
        integer(i4_kind), intent(in) :: val !< The value to initialize to

        select rank (arr)
          rank(1)
            arr = val
          rank(2)
            arr = val
          rank(3)
            arr = val
          rank(4)
            arr = val
          rank(5)
            arr = val
        end select
      end subroutine arr_init_i4
