      integer(i4_kind), intent(out)  ::  local(:,:,:,:,:)
      integer(i4_kind), intent(in) :: global(:,:,:,:,:)
      integer, intent(in), optional :: flags
      integer, intent(in), optional :: position
      integer, intent(in), optional :: tile_count
      integer(i4_kind), intent(in), optional :: default_data

      integer(i4_kind) :: local3D (size( local,1),size( local,2),size( local,3)*size( local,4)*size(local,5))
      integer(i4_kind) :: global3D(size(global,1),size(global,2),size(global,3)*size(global,4)*size(local,5))
      pointer( lptr, local3D  )
      pointer( gptr, global3D )
      local = 0
      lptr = LOC(local)
      gptr = LOC(global)
      call mpp_global_field_ad( domain, local3D, global3D, flags, position,tile_count, default_data )
    end subroutine mpp_global_field2D_i4_5d_ad
